const invertColorsPass = new ShaderPass(InvertColorsShader)
invertColorsPass.enabled = !!cfg.invertColorsEnabled
composer.addPass(invertColorsPass)
composer.addPass(new OutputPass())

const hemiLight = new THREE.HemisphereLight(cfg.ambientSkyColor, cfg.ambientGroundColor, cfg.ambientIntensity)
scene.add(hemiLight)
const keyLight = new THREE.DirectionalLight(cfg.keyColor, cfg.keyIntensity)
scene.add(keyLight)
scene.add(keyLight.target)
function updateKeyLightPosition() {
  const az = THREE.MathUtils.degToRad(cfg.keyAzimuth)
  const el = THREE.MathUtils.degToRad(cfg.keyElevation)
  const r = sceneState.fieldRadius * 3
  keyLight.position.set(r * Math.cos(el) * Math.cos(az), r * Math.sin(el), r * Math.cos(el) * Math.sin(az))
  keyLight.target.position.set(0, (cfg.keyTargetHeight / 100) * sceneState.fieldRadius, 0)
  keyLight.target.updateMatrixWorld()
}

const gridHelper = new THREE.GridHelper(40, 20, 0x444466, 0x2a2a36)
gridHelper.rotation.x = Math.PI / 2
gridHelper.visible = cfg.showGridHelper
scene.add(gridHelper)

const targetMarker = new THREE.Mesh(new THREE.SphereGeometry(1, 12, 12), new THREE.MeshBasicMaterial({ color: 0xff5566 }))
targetMarker.visible = cfg.showTargetMarker
scene.add(targetMarker)

// -----------------------------------------------------------------------
// Cursor -> world target
// -----------------------------------------------------------------------
window.addEventListener('pointermove', (e) => {
  // Ported pattern, see lib/visibility-tick-loop.js's own "CURSOR/MOUSE
  // TRACKING" header section -- this handler used to write into cursorNDC
  // completely unconditionally, tracking input for a page nobody could
  // see while hidden/unfocused (a background tab, covered by another app
  // window). animate() itself already stops being called under those same
  // conditions (see its own comment), so skipping this too keeps
  // cursorNDC from silently going stale-vs-fresh across a pause/resume
  // boundary and matches the exact same signal the render loop uses.
  if (window.VisibilityTickLoop.isPaused()) return
  cursorNDC.set((e.clientX / window.innerWidth) * 2 - 1, -(e.clientY / window.innerHeight) * 2 + 1)
  lastPointerClientX = e.clientX
  lastPointerClientY = e.clientY
})
// Mouse Tracking Log (Debug group) -- direct request: a click log (location
// + what it triggered) plus a regular, interval-driven cursor-position
// log. The click log runs unconditionally (a click is discrete/rare enough
// that logging it costs nothing); "what it triggers" describes this app's
// OWN actual click semantics honestly, not a placeholder -- a click lands
// either inside the dev panel itself, or on the canvas, where this
// project's OrbitControls config (LEFT/RIGHT = pan, MIDDLE = dolly/zoom,
// see its own setup comment) is what actually responds to it; there is no
// OTHER click-triggered interaction in this app yet (no clickable hands).
//
// REWRITTEN 2026-09-28 -- direct request: "make a log entry for both the
// click hold, as well as the release. so they are 2 separate entries. and
// stop labeling any click drag as OrbitControls" + "the mouse log should
// also differentiate between a click, clickhold, as well as multi click/
// multiclick holds... a clickhold is not the same as a click." A
// Click+Hold is now a GENUINELY DIFFERENT logged category from a Click,
// not a "Click"/"Drag-release" label with a heldMs number attached --
// and it produces 2 separate log lines (a "...-start" the moment the
// hold is confirmed, WHILE the button is still down, and a matching
// "...-release" at pointerup), never one combined line.
//
// `mouseLogChainCount` (module-level, see its own declaration) is
// incremented at PRESS time now, not release -- the hold-confirm timer
// below fires WHILE a button is still down, before release, so it needs
// this hand's own chain position (1st/2nd/3rd/4th rapid press) available
// before release ever happens. The quick-click debounce path (bottom of
// pointerup) reads the SAME counter, so a press that becomes a hold and
// a press that stays quick never disagree about which ordinal they were.
//
// "OrbitControls" is gone from every label -- it's an implementation
// detail, not something the user did. A genuine drag (real cursor
// movement while held, released before the hold-confirm threshold) is
// still labeled "Camera Pan"/"Camera Zoom/Dolly" since that's really
// what it does, just without naming the library. A press that's held
// past the threshold WITHOUT moving is no longer folded into that same
// "drag" bucket at all -- it's "Click+Hold" (or "Right-Click+Hold" etc.),
// since that's the actual gesture a Click+Hold custom function responds
// to, and mislabeling it as a camera pan (which OrbitControls never
// actually performed, since nothing moved) was directly misleading when
// correlating this log against the Hand Behaviour Log below.
const MOUSE_LOG_MOVE_THRESHOLD_PX = 10
// CORRECTED 2026-10-01, direct bug report: "click functions don't really
// work on mobile." Root cause: a real finger tap on a touchscreen
// naturally has more positional jitter between touchstart and touchend
// than a mouse click does -- MOUSE_LOG_MOVE_THRESHOLD_PX (10px) is tight
// enough that an ordinary mobile tap can exceed it even with no
// intentional movement, misclassifying every mobile multi-click release
// as "moved too far" (a drag) in the 2 dispatch-affecting call sites below
// (the click-hold CHAIN's own "moved" check, and this file's own
// multi-click debounce's "genuine hold/drag" check, added 2026-09-30 --
// see that section's own comment). That misclassification silently
// zeroes the click count/cancels the pending resolution -- the SEPARATE
// Mouse Tracking Log classifier (line ~2225 below) has its own identical
// vulnerability but only affects a LOG LABEL, which is why the user's
// own log still correctly showed "Double-Click"/etc. while the REAL
// dispatch silently failed. Fixed by using a touch-aware threshold at
// all 3 call sites instead of the one flat constant. 30px for touch is a
// disclosed judgment call (no measured touch-slop data for this specific
// app/device), not a measured value -- loosely in line with Android's
// own documented system touch-slop (~8dp, which is noticeably more than
// 10 CSS px on most real device pixel ratios), picked generously rather
// than tuned precisely.
const MOUSE_LOG_MOVE_THRESHOLD_PX_TOUCH = 30
