  const values = {}
  POSE_PRESET_KEYS.forEach((k) => { values[k] = item[k] !== undefined ? item[k] : POSE_KEY_DEFAULTS[k] })
  // CORRECTED 2026-09-19 -- loadingPreviewRotationX/Y/Z (the dev-panel
  // SLIDER) used to be folded in here (rotating the hand itself);
