// Row visibility for the Loading Preview's own Sequence Mode controls --
// same 2-level gating as updateSequencePlayModeVisibility() (Count's own
// Sequence Count/Count Mode; Loop Transition only for a Loop-style
// repeat), minus the Mode check that function also does (there's no
// Single-Pose-vs-Sequence distinction here -- the Loading Preview group
// is ALWAYS about sequence playback).
function updateLoadingPreviewSequenceVisibility() {
  const setRow = (suffix, visible) => {
    const row = document.querySelector(`.dp-row[data-key="loadingPreviewSequence${suffix}"]`)
    if (row) row.style.display = visible ? '' : 'none'
  }
  const playMode = cfg.loadingPreviewSequenceMode
  const isCount = playMode === 'Count'
  setRow('Count', isCount)
  setRow('CountMode', isCount)
  setRow('LoopTransition', playMode === 'Loop' || (playMode === 'Count' && cfg.loadingPreviewSequenceCountMode === 'Loop'))
  // Direct request 2026-09-20: in Count mode, per-lap speed is now
  // DERIVED from Min Loading Time / Count (see updateLoadingPreviewAnimation()'s
  // own comment) -- hide the manual Speed slider then, since setting it
  // would silently do nothing.
  const speedRow = document.querySelector('.dp-row[data-key="loadingPreviewSpeedMs"]')
  if (speedRow) speedRow.style.display = isCount ? 'none' : ''
}
// Plays the selected Tween Sequence (every named pose in it) for as
// long as the loading screen stays up, per the Sequence Mode
// (Count/Loop/Oscillate) settings -- same lap-based mechanism as
// updateClickPoseForHand()'s own 'sequencePlaying' phase (see
// makeClickPoseGroup()'s own control comment for the full reasoning),
// generalized to module-level state (a single instance, not per-hand)
// instead of per-hand `cp` state, and with no "release" concept at all
// (this preview just plays until the page itself finishes loading).
// 'Count' mode freezes at the last pose reached once its laps are used
// up (`loadingPreviewSequenceDone`) rather than doing anything further --
// there's no pause/retransition concept for a loading animation. Falls
// back to just holding the default pose (no visible motion, but still a
// rendered hand) when no sequence is selected or it resolves to zero
// poses.
// CORRECTED 2026-09-19, direct report ("the loading preview is still
// starting and ending with the default pose. I dont want that") -- this
// used to prepend `poseDefaultValues` as the sequence's own lead-in
// anchor (`[poseDefaultValues, ...namedPoses]`), the same convention
// chp/rchp's own Tween Mode uses for ITS sequences. That's wrong for
// this preview specifically: every lap (and every oscillation swing)
// tweened INTO and back OUT OF the default pose regardless of what the
// selected sequence's own named poses actually were. Now plays exactly
// the selected sequence's own poses, nothing else -- no default-pose
// anchor at either end.
function updateLoadingPreviewAnimation() {
  const seq = (cfg.savedTweenSequences || []).find((s) => s.name === cfg.loadingPreviewTweenSelector)
  const rawEntries = seq ? (seq.tweenPoses || []) : []
  // CORRECTED 2026-09-20, direct report ("the imported tweens still dont
  // seem to read the Hold data") -- this used to call
  // resolveTweenSequencePoses(seq.tweenPoses), which maps EVERY entry
  // through `.filter((p) => p.name === name)` assuming it's a pose-name
  // STRING; a Hold entry (`{type:'hold', percent}`, isHoldEntry()'s own
  // shape) silently never matches anything there and gets dropped
  // entirely -- exactly the reported symptom, for the SAME underlying
  // reason resolveTweenSegmentsWithAnchor()/lerpTweenSegments() (the
  // Hold-aware pathway chp/rchp/etc. already use) were built in the
  // first place; this consumer just never got switched onto it. `anchor`
  // is the first REAL pose-name entry (skipping any leading Hold, which
  // has "nothing before it" and would be a no-op per
  // resolveTweenSegmentsWithAnchor()'s own comment) -- this preserves
  // the EXISTING "plays from the sequence's own first named pose, no
  // default-pose anchor at either end" convention (see the comment above
  // this function) rather than introducing a new one.
  const anchorIdx = rawEntries.findIndex((e) => typeof e === 'string' && e)
  const anchorMatches = anchorIdx >= 0 ? (cfg.savedPoses || []).filter((p) => p.name === rawEntries[anchorIdx]) : []
  const anchorPose = anchorMatches[anchorMatches.length - 1]
  if (!anchorPose) {
    if (!loadingPreviewNoSequenceLogged) {
      loadingPreviewNoSequenceLogged = true
      logLoadingPreview(`no playable tween: selected "${cfg.loadingPreviewTweenSelector || '(none)'}", ${seq ? 'found with ' + rawEntries.length + ' entries but its first pose is not in Saved Poses' : 'not found in Saved Tween Sequences'} -- showing the default pose`)
    }
    applyLoadingPreviewPose(poseDefaultValues)
    return
  }
  if (loadingPreviewSequenceDone) return // frozen at whatever was last applied
  const segments = resolveTweenSegmentsWithAnchor(anchorPose, rawEntries.slice(anchorIdx + 1))
  const lastPose = segments.length > 0 ? segments[segments.length - 1].poseB : anchorPose
  const playMode = cfg.loadingPreviewSequenceMode
  const lapStyle = playMode === 'Count' ? cfg.loadingPreviewSequenceCountMode : playMode
  const totalLaps = playMode === 'Count' ? Math.max(cfg.loadingPreviewSequenceCount || 1, 1) : Infinity
  const holdMs = Math.max(cfg.loadingPreviewSequenceHoldMs || 0, 0)
  const now = performance.now()
  if (loadingPreviewHoldEndMs && now < loadingPreviewHoldEndMs) return // mid-hold -- last applied pose stays, nothing to reapply (no other config drives this preview's own idle state)
  if (loadingPreviewHoldEndMs && now >= loadingPreviewHoldEndMs) {
    loadingPreviewHoldEndMs = 0
    loadingPreviewLapStartMs = now
    if (lapStyle === 'Oscillate') loadingPreviewDirection *= -1
  }
  // Direct request 2026-09-20: "if i set the loading preview to Count...
  // The duration of this entire tween should be whatever is set the
  // Minimum loading duration to be. If i set the count to 2, it will
  // run through the sequeunce twice [in that same total time]." In
  // Count mode, each lap's own speed is DERIVED from
  // `loadingMinTimeMs / totalLaps` instead of the manually-set
  // `loadingPreviewSpeedMs` slider, so `totalLaps` laps together take
  // exactly `loadingMinTimeMs` regardless of count -- Loop/Oscillate
  // keep using the slider as-is, since they have no natural "total
  // duration" (they just play until the real field starts).
  const speedMs = playMode === 'Count'
    ? Math.max((cfg.loadingMinTimeMs || 0) / totalLaps, 1)
    : Math.max(safeTweenSpeedMs(cfg.loadingPreviewSpeedMs), 1)
  const lapT = THREE.MathUtils.clamp((now - loadingPreviewLapStartMs) / speedMs, 0, 1)
  let values
  if (segments.length === 0) {
    // Only the anchor pose itself, nothing after it (a single-pose
    // sequence, or every entry after the anchor was empty) -- same
    // degenerate case the old lerpTweenSequence([onePose], t) handled by
    // just returning that one pose's own values, static.
    values = anchorPose
  } else if (lapStyle === 'Oscillate') {
    const t = loadingPreviewDirection === 1 ? lapT : 1 - lapT
    values = lerpTweenSegments(segments, t)
  } else if (cfg.loadingPreviewSequenceLoopTransition === false) {
    values = lerpTweenSegments(segments, lapT) // instant jump back to frame 1 between laps -- same forward pass every time, no wrap interpolation
  } else {
    // Smooth wrap-back -- same cyclic-ring approach lerpLoopSequence()
    // used before this fix, generalized to WEIGHTED segments (a Hold's
    // own weight can differ from a real pose-to-pose transition's weight
    // of 1): the ring is this lap's own forward segments plus one
    // CLOSING segment back from the last pose to the anchor, so the
    // wrap-back point is included in the same weighted timeline instead
    // of being a separate equal-weight step the way it implicitly was
    // when every segment had weight 1.
    const ringSegments = segments.concat([{ poseA: lastPose, poseB: anchorPose, weight: 1 }])
    const totalRingWeight = ringSegments.reduce((sum, seg) => sum + seg.weight, 0)
    const tCyclic = (loadingPreviewLapIndex - 1 + lapT) * totalRingWeight
    values = lerpLoopSegments(ringSegments, tCyclic)
  }
  applyLoadingPreviewPose(values)
  if (lapT >= 1) {
    logLoadingPreview(`lap ${loadingPreviewLapIndex} complete (${playMode}${playMode === 'Count' ? ' of ' + totalLaps : ''})`)
    loadingPreviewLapIndex++
    if (loadingPreviewLapIndex > totalLaps) {
      loadingPreviewSequenceDone = true
      logLoadingPreview('sequence finished -- holding the last pose')
    } else if (holdMs > 0) {
      loadingPreviewHoldEndMs = now + holdMs
    } else {
      loadingPreviewLapStartMs = now
      if (lapStyle === 'Oscillate') loadingPreviewDirection *= -1
    }
  }
}

// -----------------------------------------------------------------------
// Pose Preview -- a small, independent Three.js viewport embedded in the
// dev panel's own collapsible "Pose Preview" group (direct user request:
// "Use" should NOT repose every hand in the field). Its own scene/camera/
// renderer/OrbitControls/hand clone, entirely separate from the main
// field -- never touches `hands`, `cfg`, or `cloneBaseQuat`.
// -----------------------------------------------------------------------
let previewHand = null // { clone, skinnedMesh }
let previewRenderer = null
let previewScene = null
let previewCamera = null
let previewControls = null
let posePreviewPanel = null // the floating panel element itself, once built
const previewBaseQuat = new THREE.Quaternion()
const _previewWholeHandRotEuler = new THREE.Euler()
const POSE_PREVIEW_CAMERA_KEY = 'hd-pose-preview-camera-default'
const POSE_PREVIEW_MIN_W = 220
const POSE_PREVIEW_MIN_H = 200

// Restores this hand's default framing (the same one-time bounding-sphere
// auto-frame buildPosePreview() always falls back to) -- shared by both
// the initial build and a future "reset" if ever needed.
function defaultPosePreviewCamera() {
  const target = handBoundsCenterLocal.clone().applyQuaternion(alignQuat)
  // CORRECTED 2026-09-19 -- same distance-too-close bug as
  // applyLoadingPreviewCameraAutoFrame()'s own identical formula, fixed
  // together; see that function's own comment for the full math.
  const pos = target.clone().add(new THREE.Vector3(0, handBoundsRadiusLocal * 0.15, handBoundsRadiusLocal * 3.6))
  return { pos, target }
}
// "Set Default Camera" (direct request) -- captures the preview's OWN
// current camera position/orbit-target and persists it (localStorage,
