  'Triple-Click Pose': 'tripleClick',
  'Quadruple-Click Pose': 'quadClick',
  'Right Click': 'rc',
  'Double Click Hold': 'dcHold',
  'Triple-Click Hold': 'tripleClickHold',
  'Quadruple-Click Hold': 'quadClickHold'
